/**
 * GLOSSARY — keep these terms consistent across all translations.
 * If updating, search the file and update every occurrence.
 *
 * boutique / shop                  → متجر
 * freelance / freelancer           → مستقل
 * service                          → خدمة
 * produit / product                → منتج
 * commande / order                 → طلب
 * mission / job / job post         → مهمة
 * signalement / report             → بلاغ
 * utilisateur / user               → مستخدم
 * vendeur / seller                 → بائع
 * acheteur / buyer                 → مشتر
 * livraison / delivery             → توصيل
 * paiement à la livraison (COD)    → الدفع عند الاستلام
 * profil                           → الملف الشخصي
 * tableau de bord                  → لوحة التحكم
 * modération                       → مراجعة الإشراف
 * support                          → الدعم
 * Tunisie                          → تونس
 * gouvernorat                      → ولاية
 * dinar tunisien (DT)              → دينار تونسي (د.ت)
 *
 * Conventions:
 * - Modern Standard Arabic (الفصحى), not Tunisian dialect.
 * - Western numerals (1, 2, 3), the commercial norm in Tunisia.
 * - {placeholder} tokens are preserved exactly as in fr.ts.
 * - Currency code mirrors fr.ts: fr uses "TND", so ar keeps "TND".
 * - signup.lang_fr / signup.lang_ar stay in their native script
 *   (a language label is written in its own language).
 */

