  // ─── Landing — Section 7 (FAQ) ──────────────────────────────────────────────
  'landing.faq.q1': "كيف يمنع Servyou عمليات الاحتيال؟",
  'landing.faq.a1': "يخضع جميع البائعين للتحقق عند التسجيل. يمكن للمشترين الإبلاغ عن أي مشكلة، ويتدخل فريقنا خلال 48 ساعة. يحميك الدفع عند الاستلام: لا تدفع إلا عندما تستلم المنتج وتتحقق منه.",
  'landing.faq.q2': "وماذا لو لم يكن المنتج الذي تم تسليمه هو ما طلبته؟",
  'landing.faq.a2': "يمكنك رفض الاستلام. لا يُطلب أي دفع ما لم تؤكد استلام المنتج بحالة سليمة.",
  'landing.faq.q3': "هل يأخذ Servyou عمولة؟",
  'landing.faq.a3': "لا. عند الإطلاق، يكون Servyou مجانيا تماما للجميع — مشترين ومتاجر ومستقلين. أي تغيير مستقبلي في الأسعار سيُعلن بوضوح، مع إشعار مسبق ودون مفاجآت. لا رسوم خفية أبدا.",
  'landing.faq.q4': "هل تُباع بياناتي لأطراف ثالثة؟",
  'landing.faq.a4': "أبدا. لا تُشارك معلوماتك إلا مع البائعين الذين تتعامل معهم مباشرة. لا متتبعون من جهات خارجية، ولا إعلانات موجهة. يطبق Servyou أصرم معايير حماية البيانات في العالم — اللائحة الأوروبية العامة لحماية البيانات (RGPD).",
  'landing.faq.q5': "لماذا الفرنسية والعربية، وليس الإنجليزية؟",
  'landing.faq.a5': "صُمم Servyou للتونسيين أولا. تغطي الفرنسية والعربية الاستعمال اليومي. ستأتي الإنجليزية لاحقا إذا طلبها المجتمع.",
  'landing.faq.q6': "إذا كيف يكسب Servyou المال؟",
  'landing.faq.a6': "عند الإطلاق، يكون Servyou مجانيا تماما. أولويتنا هي بناء الاقتصاد أولا، لا انتزاع القيمة على الفور. وعندما يصبح نموذج للإيرادات ضروريا، سيُعلن عنه بوضوح مسبقا — لا في مفاجأة أبدا، ولا في خفاء. التزامنا بالشفافية حول المال نهائي.",

