  // ─── About page (/a-propos) ──────────────────────────────────────────────────
  'about.headline':   "بيت حقيقي للاقتصاد التونسي",
  'about.subtitle':   "قصة Servyou، بقلم مؤسسها.",
  'about.story.p1':   "اسمي معتز ز. أنا تونسي، وقد بنيتُ Servyou وحدي، أتعلم البرمجة وأنا أبنيه. استعنتُ بالذكاء الاصطناعي ليساعدني — من الصدق أن أقول ذلك، وهو ما مكنني من إطلاق منصة بحجم طموحاتي دون فريق من المهندسين.",
  'about.story.p2':   "في تونس، أولئك الذين يُديرون الاقتصاد الرقمي — المستقلون، المتاجر الصغيرة، التجار — ليس لديهم بيت حقيقي. يبيعون على إنستغرام بلقطات شاشة لتحويلات بنكية. يتلقون طلبات على واتساب تضيع. لم تكن هناك منصة مبنية لتونس، بالدينار التونسي، بإشارات الثقة التي تحتاجها التجارة الحقيقية. وُجد Servyou لسد هذا الفراغ.",
  'about.story.p3':   "أدركتُ أن الحل ليس نسخة من Fiverr أو Etsy أو Amazon مترجمة إلى الفرنسية. تستحق تونس منصة مصممة منذ البداية لواقعها — الدفع عند الاستلام، الولايات الأربع والعشرون، اللغات التي نتحدثها فعلا، والعادات التي نملكها أصلا. Servyou هو هذه المنصة.",
  'about.story.p4':   "Servyou في مرحلة النسخة التجريبية الأولى. أتعلم من كل مستخدم. إن كلمتني، أقرأ رسالتك بنفسي. وإن وجدت مشكلة، أُصلحها. هذا القرب سيتلاشى مع نمو المنصة، وهذا أمر جيد — لكن اليوم، هذا وعدي.",
  'about.values.heading': "قيمنا الثلاث",
  'about.values.v1.title': "نحمي مستخدمينا.",
  'about.values.v1.body':  "بُني Servyou لحماية الناس من الخداع والاحتيال والاستغلال. يُختبر كل قرار أمام سؤال واحد: هل يجعل المستخدمين أكثر أمانا، أم يعرضهم للخطر؟ حين يتعارض الأمان مع الراحة، يفوز الأمان. وحين يتعارض الأمان مع الربح، يفوز الأمان.",
  'about.values.v2.title': "نحن صادقون، خاصة في ما يخص المال.",
  'about.values.v2.body':  "لا يُخفي Servyou أي رسوم أبدا، ولا يفاجئ بأعباء غير متوقعة، ولا يستعمل فخاخا مربكة. ما يكسبه Servyou معلن بوضوح. يعرف المستخدمون دائما بالضبط ما يدفعونه وما يحصلون عليه.",
  'about.values.v3.title': "نحن تونسيون حقا، لا نسخة أجنبية.",
  'about.values.v3.body':  "صُمم Servyou من الصفر للطريقة التي يعيش بها التونسيون ويعملون ويشترون ويبيعون — بالدينار التونسي، عبر الولايات التونسية، بالفرنسية والعربية، بالأدوات والعادات التي يستعملها التونسيون أصلا.",
  'about.cta.tagline':   "مستعد للانضمام إلى Servyou؟",
  'about.cta.primary':   "إنشاء حساب مجاني",
  'about.cta.secondary': "اتصل بنا",

